def cp(a,b):
 if Path(a).suffix.lower() in {'.jpg','.jpeg','.png','.pdf','.npy','.npz'}:os.link(a,b)
 else:shutil.copy2(a,b)
if not S.exists():shutil.copytree(O/'source-report',S,copy_function=cp)
for d in ['hub','hub/data','hub/figures']:(S/d).mkdir(exist_ok=True)
a=load(T/'atlas_final.json');add=load(O/'ai-inspection-completion.json');new={r['concept_id']:r for r in add['records']};st=load(W/'workstream_status.json');cs=a['classes'];ks=[k for c in cs for k in c['concepts']];ids=[k['id'] for k in ks]
assert len(ids)==len(set(ids))==157 and sum(not k['is_complement'] for k in ks)==147
assert len(new)==99 and set(new)=={k['id'] for k in ks if not k.get('ai_description')}
nh=0
for c in cs:
 assert c['metrics']['training_images']==400 and c['metrics']['validation_images']==50
 for k in c['concepts']:
  if k['id'] in new:
   r=new[k['id']];k['ai_description']=r['ai_description'];k['ai_review_findings']=[r['findings']]
   lookup={e['id']:e for v in k['views'].values() for e in v['examples']}
   for e in r['evidence']:
    assert e['id'] in lookup
    for typ in ['region','overlay']:assert sha(S/lookup[e['id']][typ])==e[typ+'_sha256'];nh+=1
accepted={(r['class_name'],r['method'],r['evaluation']) for r in st['rows'] if r['state']=='ACCEPTED'}
for c in cs:
 for m in ['HU-MCD','Random']:
  for d in ['C-Insertion','C-Deletion']:assert (c['name'],m,d) in accepted,(c['name'],m,d)
for c in cs:
 c['metrics']['evaluation']='HU-MCD + Random: both directions ACCEPTED'
 c['metrics']['evaluation_short']='ACCEPTED'
for m in ['MCD','ACE']:
 for d in ['C-Insertion','C-Deletion']:assert ('golden_retriever',m,d) in accepted
rob=rows(BR/'robustness-conditions.csv');ra=load(BR/'acceptance-A.json')['robustness'];ext=load(EX/'acceptance.json')
