B=R/'artifacts/bunya/nine-class-baselines-20260923';batch=load(B/'batch.json');assert batch['status']=='SUBMITTED' and len(batch['entries'])==63
sources=[B/'batch.json',B/'post-submission-scheduler.json',B/'stage_status.csv',T/'atlas_final.json',W/'workstream_status.json',F/'analysis.json',F/'semantic-replay.json',F/'golden_native_points.csv',W/'analysis/ten_class_pooled_points.csv',BR/'acceptance-A.json',BR/'acceptance-B.json',BR/'robustness-conditions.csv',EX/'acceptance.json',EX/'contrasts.csv',R/'artifacts/bunya/medical-results-20260922/acceptance.json',O/'ai-inspection-completion.json']
manifest=[]
for src in sources:
 name=src.parent.name+'--'+src.name;shutil.copy2(src,S/'hub/data'/name);manifest.append({'path':str(src),'copy':'hub/data/'+name,'sha256':sha(src)})
(S/'hub/data/source-manifest.json').write_text(json.dumps(manifest,indent=2));(S/'hub/data/presentation-atlas.json').write_text(json.dumps(a,ensure_ascii=False))
