ax[1].scatter([c['metrics']['completeness'] for c in cs],y,label='Our results',color='#087f8c');ax[1].scatter([float(c['metrics']['paper_completeness_rounded']) for c in cs],y,marker='x',label='Paper rounded to 2 decimals',color='#ba6225');ax[1].set(yticks=y,yticklabels=names,xlabel='Completeness (weight-space coverage)',xlim=(.5,.9));ax[1].invert_yaxis();ax[1].legend(fontsize=9);fig.suptitle('Ten-class reference reproduction | 400 training / 50 validation images per class');save('ten-class',fig)
for name,path,g in [('ten-evaluation',W/'analysis/ten_class_pooled_points.csv',False),('golden-evaluation',F/'golden_native_points.csv',True)]:
 rr=rows(path);fig,axs=plt.subplots(1,2,figsize=(12,5),layout='constrained')
 for ax,d in zip(axs,['C-Deletion','C-Insertion']):
  for m in dict.fromkeys(r['method'] for r in rr):
   q=[r for r in rr if r['method']==m and r['direction']==d]
   if not q:continue
   xx=[float(r[('deleted_pixels_percent' if g else 'deleted_pixel_percent') if d=='C-Deletion' else ('visible_pixels_percent' if g else 'visible_pixel_percent')]) for r in q];yy=[float(r['accuracy'])*100 for r in q];ns=[int(r['contributors' if g else 'contributing_images']) for r in q]
   ax.plot(xx,yy,'o-',label=('ACE released-code reference' if m in ['ACE','ACE-R'] else ('Random (n=50)' if g else 'Random (n=500)') if m=='Random' else m),color=colors.get(m),ms=4,lw=1.3)
   if m!='Random':
    for x,v,n in list(zip(xx,yy,ns))[1:]:ax.annotate(str(n),(x,v),xytext=(3,4),textcoords='offset points',fontsize=7,color=colors.get(m))
  ax.set(title=d,xlabel='Deleted pixels (%)' if d=='C-Deletion' else 'Visible pixels (%)',ylabel='Target-class accuracy (%)',ylim=(-2,103),xlim=(-2,102));ax.grid(alpha=.15);ax.legend(fontsize=8)
 fig.suptitle(('Golden Retriever | Different discovery sizes and ranking rules' if g else 'Ten classes | Pooled image-level trajectories')+'\nLabels: contributing images; native computed points only',fontsize=12);save(name,fig)
from research_hub.robustness_figure import build as build_robustness_figure
