fig,ax=plt.subplots(1,2,figsize=(11,4.5),layout='constrained');labels=['Source training','Source held-out','External MEL']
for vals,bottom,label,color in [([514,82,94],[0,0,0],'Learned concept','#087f8c'),([335,61,165],[514,82,94],'Complement','#9baeba'),([68,14,37],[849,143,259],'Zero feature','#c66c43')]:ax[0].bar(labels,vals,bottom=bottom,label=label,color=color)
ax[0].set(ylabel='Region count',title='One frozen concept + complement');ax[0].legend(fontsize=9);ax[1].bar(['Source held-out\n50 / 70 images','External MEL\n29 / 101 cases'],[50/70*100,29/101*100],color=['#087f8c','#8055a2']);ax[1].set(ylim=(0,100),ylabel='Predicted as MEL (%)',title='Different cohorts: descriptive only');fig.suptitle('Medical transfer | Counts do not establish clinical utility');save('medical',fig)
def E(x):return html.escape(str(x),quote=True)
def bi(z,e):return f'<span data-l="zh">{E(z)}</span><span data-l="en" hidden>{E(e)}</span>'
def p(z,e,cls=''):return f'<p class="{cls}">{bi(z,e)}</p>'
def h(z,e,n=2):return f'<h{n}>{bi(z,e)}</h{n}>'
def link(url,z,e):return f'<a href="{E(url)}">{bi(z,e)}</a>'
def table(headers,data):return '<div class="table-scroll"><table><thead><tr>'+''.join('<th>'+bi(*x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in data)+'</tbody></table></div>'
def figure(path,z,e):return f'<figure><a href="{path}" target="_blank"><img src="{path}" alt="{E(e)}" loading="lazy"></a><figcaption>{bi(z,e)}</figcaption></figure>'
nav=[('index.html','总览','Overview'),('reproduction.html','方法复现','Reproduction'),('robustness.html','分割稳定性','Segmentation sensitivity'),('medical.html','医学迁移','Medical transfer'),('human-review.html','人工校验','Human review'),('paper-comparison.html','论文对照','Paper comparison'),('issues.html','疑点与限制','Issues & limits'),('evidence.html','证据附录','Evidence'),('glossary.html','术语','Glossary')]
