 text='<!doctype html><html lang="zh" data-lang="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(title[0])+' | HU-MCD</title><link rel="stylesheet" href="'+pre+'hub/style.css"><script defer src="'+pre+'hub/app.js"></script></head><body data-hub="1" data-dataset="'+E(a['dataset_id'])+'"><a class="skip" href="#main">'+bi('跳到正文','Skip to content')+'</a><header><a class="brand" href="'+pre+'index.html">HU-MCD <small>'+bi('研究结果','Research results')+'</small></a><button id="language" aria-label="Switch language">English</button></header><nav>'+bars+'</nav><main id="main"><div class="eyebrow">'+bi('私有研究报告 · 数据截止 2026-09-23','Private research report · Evidence through 23 Sep 2026')+'</div>'+h(*title,1)
 if crumb:text+='<div class="crumb">'+crumb+'</div>'
 text+=body+'</main><footer>'+bi('AI 描述待人工确认；工程验收不等于语义或临床验证。','AI descriptions await human confirmation; engineering acceptance is not semantic or clinical validation.')+'<br>'+link(pre+'evidence.html','来源、版本与生成记录','Sources, versions and generation record')+' · '+link('#main','返回顶部','Back to top')+'</footer><script id="concept-ids" type="application/json">'+json.dumps(ids)+'</script></body></html>'
 dst=S/path;dst.parent.mkdir(parents=True,exist_ok=True);dst.write_text(text)
