terms=[('HU-MCD','Human-Understandable Multi-Dimensional Concept Discovery，人类可理解的多维概念发现。','Human-Understandable Multi-Dimensional Concept Discovery.'),('SSC','Sparse Subspace Clustering，稀疏子空间聚类：用其他特征的稀疏组合表示特征，再按关联聚类；与后续子空间拟合分开。','Sparse Subspace Clustering: represent features sparsely using others, then cluster by affinities; distinct from subsequent subspace fitting.'),('ssc / sdc','benchmark 内部方向标识：ssc 对应 C-Insertion，sdc 对应 C-Deletion。这里不是聚类算法名，不猜测未说明的英文展开。','Internal benchmark direction flags: ssc selects C-Insertion, sdc C-Deletion. This is not the clustering algorithm; no undocumented expansion is inferred.'),('MCD','Multi-Dimensional Concept Discovery，多维概念发现基线。','Multi-Dimensional Concept Discovery, a comparison baseline.'),('ACE','Automated Concept-based Explanations，自动概念解释；本报告是 HU-MCD released-code reference。','Automated Concept-based Explanations; this report uses the HU-MCD released-code reference.'),('SAM / ViT-H','Segment Anything Model / Vision Transformer Huge：掩码生成模型及其大型视觉 Transformer 版本。','Segment Anything Model / Vision Transformer Huge: the mask generator and its large vision-transformer variant.'),('PCA','Principal Component Analysis，主成分分析；用于概念子空间拟合。','Principal Component Analysis, used for concept-subspace fitting.'),('CAV / TCAV','Concept Activation Vector / Testing with Concept Activation Vectors；概念方向及方向导数敏感性测试，不是人类可理解性分数。','Concept Activation Vector / Testing with Concept Activation Vectors: concept directions and directional-derivative sensitivity, not human-understandability scores.'),('SLIC','Simple Linear Iterative Clustering，图像超像素分割方法；ACE 用它生成候选区域。','Simple Linear Iterative Clustering, a superpixel segmentation method used by ACE to generate candidate regions.'),('OC / complement','Orthogonal complement，正交补空间：学习子空间之外的特征方向；不等于图像背景，不计入学习概念。','Orthogonal complement: feature directions outside learned subspaces; not synonymous with image background and not counted as learned concepts.'),('Completeness','分类权重被学习子空间覆盖的比例；不是重构误差、纯度或可理解性。','Classifier-weight coverage by learned subspaces; not reconstruction error, purity or understandability.'),('C-Insertion / C-Deletion','按概念顺序逐步显示／删除区域，观察准确率；要同时看实际像素比例和贡献人数。','Reveal/delete regions in concept order and measure accuracy; inspect actual pixel fractions and contributor counts too.'),('IoU','Intersection over Union，交并比；这里比较扰动掩码，无人工参考时不代表分割准确率。','Intersection over Union; here it compares perturbed masks, not segmentation accuracy without a human reference.'),('AUC / AUROC','Area Under the Receiver Operating Characteristic Curve，ROC曲线下面积；衡量排序区分。征象关联和疾病分类的 AUC 任务不同。','Area Under the Receiver Operating Characteristic Curve, a ranking-discrimination measure. Sign-association and disease-classification AUC concern different tasks.'),('MEL / DF','Melanoma / Dermatofibroma，黑色素瘤／皮肤纤维瘤标签；模型标签不是临床诊断。','Melanoma / Dermatofibroma labels; model labels are not clinical diagnoses.'),('AKIEC / BCC / BKL / NV / VASC','光化性角化及表皮内癌／基底细胞癌／良性角化样病变／黑色素细胞痣／血管性病变。','Actinic keratoses and intraepithelial carcinoma / basal cell carcinoma / benign keratosis-like lesions / melanocytic nevi / vascular lesions.'),('FP32 / AMP / TF32','32位浮点／自动混合精度／TensorFloat-32；每次运行实际配置为准，本轮没有改精度。','32-bit floating point / automatic mixed precision / TensorFloat-32; resolved configs are authoritative. No precision change this round.'),('CPU / GPU / Slurm','中央处理器／图形处理器／集群调度器；作业 ID 对应执行，提交哈希对应源码。','Central processing unit / graphics processing unit / cluster scheduler. Job IDs identify executions; commit hashes identify source versions.')]
page('glossary.html',('术语：含义与边界','Glossary: meanings and boundaries'),p('科学含义优先于内部文件名。','Scientific meaning takes precedence over internal filenames.','lead')+table([('术语','Term'),('解释','Explanation')],[[f'<code>{E(t)}</code>',bi(z,e)] for t,z,e in terms])+p('SSC 来源：concept_explainer.py 的 sparse_subspace_clustering；方向标识来源：benchmark_methods.py 的 ssc/sdc 分支。执行版本见作业证据。','SSC: sparse_subspace_clustering in concept_explainer.py. Direction flags: ssc/sdc branches in benchmark_methods.py. Execution versions are recorded in job evidence.','quiet'))
